1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export type Step = QuoteStep | ClaimStep;
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Item {
18	  type: string;
19	  material?: string;
20	  enchantment?: number;
21	  cursed?: boolean;
22	}
23	
24	export interface ClaimStep {
25	  op: "claim";
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export interface Incident {
31	  cause: string;
32	  damages: Damage[];
33	}
34	
35	export interface Damage {
36	  itemType: string;
37	  amount: number;
38	}
39	
40	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
41	
42	export interface ScenarioResult {
43	  results: StepResult[];
44	}
45	
46	const PROCESSING_FEE = 5;
47	
48	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
49	  sword: 100,
50	  staff: 80,
51	  amulet: 60,
52	  potion: 40,
53	  rune: 25,
54	  moonstone: 25,
55	};
56	
57	const FIRST_INSURANCE_PERCENT = 10;
58	
59	// Surcharges are applied as (amount * percent) / 100 rather than via a decimal
60	// multiplier (e.g. * 1.1): the integer intermediate is exact, whereas 100 * 1.1
61	// is 110.00000000000001 in binary floating point. Since the final amount feeds
62	// straight into Math.ceil, that error would round a 115 G premium up to 116 G.
63	const percentOf = (amount: number, percent: number): number =>
64	  (amount * percent) / 100;
65	
66	/**
67	 * Reads a per-type rate table, rejecting types the MHPCO does not insure.
68	 *
69	 * The rate tables all share one domain — the insurable item types — so an
70	 * absent entry means the same thing in every one of them, and is reported the
71	 * same way. Keeping the guard here rather than at each call site is what stops
72	 * the tables from drifting into one validated and one silently yielding NaN.
73	 */
74	const rateFor = (table: Record<string, number>, itemType: string): number => {
75	  const rate = table[itemType];
76	  if (rate === undefined) {
77	    throw new Error(`The MHPCO does not insure items of type "${itemType}"`);
78	  }
79	  return rate;
80	};
81	
82	const itemBasePremium = (item: Item): number =>
83	  rateFor(BASE_PREMIUM_BY_TYPE, item.type);
84	
85	const BLOCK_SIZE = 3;
86	const BLOCK_BASE_PREMIUM = 60;
87	
88	const sumItemBasePremiums = (items: Item[]): number =>
89	  items.reduce((sum, item) => sum + itemBasePremium(item), 0);
90	
91	/** Items of one and the same type, e.g. the three runes that form a block. */
92	type TypeGroup = Item[];
93	
94	const groupByType = (items: Item[]): TypeGroup[] => [
95	  ...items
96	    .reduce(
97	      (groups, item) =>
98	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
99	      new Map<string, TypeGroup>(),
100	    )
101	    .values(),
102	];
103	
104	const formsBlock = (group: TypeGroup): boolean => group.length === BLOCK_SIZE;
105	
106	const groupBasePremium = (group: TypeGroup): number =>
107	  formsBlock(group) ? BLOCK_BASE_PREMIUM : sumItemBasePremiums(group);
108	
109	const policyBasePremium = (items: Item[]): number =>
110	  groupByType(items).reduce((sum, group) => sum + groupBasePremium(group), 0);
111	
112	const CURSE_PERCENT = 50;
113	const HIGH_ENCHANTMENT_PERCENT = 30;
114	const HIGH_ENCHANTMENT_THRESHOLD = 5;
115	
116	/**
117	 * A modifier adjusts a base premium by `percent` when it `applies` to its
118	 * subject. Discounts are expressed as negative percentages, so that the
119	 * applicable rules of one scope always combine by summation.
120	 */
121	interface ModifierRule<Subject> {
122	  applies: (subject: Subject) => boolean;
123	  percent: number;
124	}
125	
126	const applicablePercent = <Subject>(
127	  rules: ModifierRule<Subject>[],
128	  subject: Subject,
129	): number =>
130	  rules.reduce(
131	    (percent, rule) => (rule.applies(subject) ? percent + rule.percent : percent),
132	    0,
133	  );
134	
135	/**
136	 * Item-scoped modifiers apply to the affected item's own base premium, not to
137	 * the policy total.
138	 */
139	const ITEM_MODIFIER_RULES: ModifierRule<Item>[] = [
140	  { applies: (item) => item.cursed === true, percent: CURSE_PERCENT },
141	  {
142	    applies: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
143	    percent: HIGH_ENCHANTMENT_PERCENT,
144	  },
145	];
146	
147	const itemSurcharge = (item: Item): number =>
148	  percentOf(itemBasePremium(item), applicablePercent(ITEM_MODIFIER_RULES, item));
149	
150	const totalItemSurcharges = (items: Item[]): number =>
151	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
152	
153	const LOYALTY_DISCOUNT_PERCENT = -20;
154	const LOYALTY_THRESHOLD_YEARS = 2;
155	const FOLLOW_UP_DISCOUNT_PERCENT = -15;
156	
157	/**
158	 * Everything a quote needs to know about the scenario around it: whose policy
159	 * this is, and how many quotes preceded it. Not the policy itself — it carries
160	 * no items, insurance sum or cap.
161	 */
162	interface QuoteContext {
163	  customer: Customer;
164	  precedingQuoteCount: number;
165	}
166	
167	/**
168	 * Policy-scoped modifiers apply to the policy base premium (the sum of all
169	 * item base premiums), independently of any item-scoped surcharges.
170	 */
171	const POLICY_MODIFIER_RULES: ModifierRule<QuoteContext>[] = [
172	  { applies: () => true, percent: FIRST_INSURANCE_PERCENT },
173	  {
174	    applies: ({ customer }) =>
175	      customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
176	    percent: LOYALTY_DISCOUNT_PERCENT,
177	  },
178	  {
179	    applies: ({ precedingQuoteCount }) => precedingQuoteCount > 0,
180	    percent: FOLLOW_UP_DISCOUNT_PERCENT,
181	  },
182	];
183	
184	const quotePremium = (step: QuoteStep, context: QuoteContext): number => {
185	  const basePremium = policyBasePremium(step.items);
186	  return Math.ceil(
187	    basePremium +
188	      percentOf(basePremium, applicablePercent(POLICY_MODIFIER_RULES, context)) +
189	      totalItemSurcharges(step.items) +
190	      PROCESSING_FEE,
191	  );
192	};
193	
194	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
195	  sword: 1000,
196	  staff: 800,
197	  amulet: 600,
198	  potion: 400,
199	  rune: 250,
200	  moonstone: 250,
201	};
202	
203	const DEDUCTIBLE = 100;
204	const CAP_MULTIPLE = 2;
205	
206	const itemInsuranceValue = (item: Item): number =>
207	  rateFor(INSURANCE_VALUE_BY_TYPE, item.type);
208	
209	const insuranceSum = (items: Item[]): number =>
210	  items.reduce((sum, item) => sum + itemInsuranceValue(item), 0);
211	
212	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
213	const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
214	
215	/**
216	 * The share of a damage amount the MHPCO reimburses before the deductible.
217	 *
218	 * The spec's dragon-material clause ("fully reimbursed") is not a separate
219	 * branch here: full reimbursement is already the default, and where dragon
220	 * material meets enchantment >= 8 the spec says the 50 % rule wins. Dragon
221	 * material therefore never changes a payout, so encoding it would add a
222	 * branch no input can distinguish.
223	 */
224	const reimbursementPercent = (item: Item): number =>
225	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
226	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT
227	    : 100;
228	
229	const damagePayout = (damage: Damage, damagedItem: Item): number =>
230	  percentOf(damage.amount, reimbursementPercent(damagedItem)) - DEDUCTIBLE;
231	
232	/**
233	 * The insured item a damage entry refers to. The MHPCO pays only for what it
234	 * insures, so a damage naming a type the policy does not cover — whether an
235	 * uninsured item or an unknown one — voids the whole claim.
236	 */
237	const damagedItem = (insuredItems: Item[], damage: Damage): Item => {
238	  const item = insuredItems.find((insured) => insured.type === damage.itemType);
239	  if (item === undefined) {
240	    throw new Error(
241	      `The policy does not cover an item of type "${damage.itemType}"`,
242	    );
243	  }
244	  return item;
245	};
246	
247	const totalPayout = (damages: Damage[], insuredItems: Item[]): number =>
248	  Math.floor(
249	    damages.reduce(
250	      (sum, damage) => sum + damagePayout(damage, damagedItem(insuredItems, damage)),
251	      0,
252	    ),
253	  );
254	
255	/**
256	 * A claim pays what the damages come to, but never more than the policy's
257	 * remaining cap — successive claims against one policy draw down a shared
258	 * budget.
259	 */
260	const cappedPayout = (
261	  damages: Damage[],
262	  insuredItems: Item[],
263	  remainingCap: number,
264	): number => Math.min(totalPayout(damages, insuredItems), remainingCap);
265	
266	/**
267	 * The policy a claim refers to. A `policy` index is only meaningful if it
268	 * points at a quote step, so the lookup narrows rather than casts; the
269	 * `undefined` case is left for the error-handling tests to give meaning.
270	 */
271	const policyAt = (steps: Step[], index: number): QuoteStep | undefined => {
272	  const step = steps[index];
273	  return step?.op === "quote" ? step : undefined;
274	};
275	
276	/**
277	 * What a scenario accumulates as it runs: the remaining cap of every policy
278	 * quoted so far (keyed by the step index a claim names as its `policy`), and
279	 * how many quotes have been issued — the follow-up discount depends on it.
280	 */
281	class Ledger {
282	  private readonly remainingCapByPolicy = new Map<number, number>();
283	  quoteCount = 0;
284	
285	  openPolicy(policyIndex: number, items: Item[]): void {
286	    this.quoteCount++;
287	    this.remainingCapByPolicy.set(policyIndex, CAP_MULTIPLE * insuranceSum(items));
288	  }
289	
290	  /** Draws `payout` down from the policy's cap and reports what is left. */
291	  drawDown(policyIndex: number, payout: number): number {
292	    const remaining = this.remainingCap(policyIndex) - payout;
293	    this.remainingCapByPolicy.set(policyIndex, remaining);
294	    return remaining;
295	  }
296	
297	  remainingCap(policyIndex: number): number {
298	    return this.remainingCapByPolicy.get(policyIndex) ?? 0;
299	  }
300	}
301	
302	export const runScenario = (scenario: Scenario): ScenarioResult => {
303	  const ledger = new Ledger();
304	
305	  const runStep = (step: Step, index: number): StepResult => {
306	    if (step.op === "quote") {
307	      const context = {
308	        customer: scenario.customer,
309	        precedingQuoteCount: ledger.quoteCount,
310	      };
311	      ledger.openPolicy(index, step.items);
312	      return { premium: quotePremium(step, context) };
313	    }
314	
315	    const insuredItems = policyAt(scenario.steps, step.policy)?.items ?? [];
316	    const payout = cappedPayout(
317	      step.incident.damages,
318	      insuredItems,
319	      ledger.remainingCap(step.policy),
320	    );
321	    return { payout, remainingCap: ledger.drawDown(step.policy, payout) };
322	  };
323	
324	  return { results: scenario.steps.map(runStep) };
325	};
